  num:'02v', tab:'—', hidden:true, vsLabel:'B  ·  SELECT … FOR UPDATE  (X 락)',
  title:'Locking Reads: FOR UPDATE Locks Like a Write', sub:'FOR UPDATE 를 붙이면 read 가 write 처럼 잠근다 — snapshot 대신 latest committed version',
