          key:'잰 값: 모드 1 과 똑같이 TABLE AUTO_INC WAITING 이 보였고 약 2초 기다렸다. <em>경합이 있을 때는 0 과 1 이 구분되지 않는다</em> — 갈리는 것은 둘째 문장이다.',
