          why:'AUTO_INC 는 문장 끝에 놓으므로, 문장 사이에 data_locks 를 보면 모드 0 · 1 · 2 가 같은 줄을 보인다 — 잰 값: 세 모드 모두 실패 뒤 TABLE IX · uk_c S · PRIMARY X supremum 세 줄. 모드 0 의 AUTO_INC 는 문장이 도는 동안이나 남이 그 뒤에서 기다릴 때만 보인다.',
